protected recordUsage(usage: TokenUsage, options?: CreateMessageOptions, reported = true): void {
  if (options?.requestVisible !== false) {
    this.usage.records.push(usage);
    this.usage.totalPromptTokens += usage.promptTokens;
    this.usage.totalCompletionTokens += usage.completionTokens;
    this.usage.totalTokens += usage.totalTokens;
    this.usage.totalCacheReadTokens += usage.cacheReadTokens ?? 0;
    this.usage.totalCacheCreationTokens += usage.cacheCreationTokens ?? 0;
    this.usage.requestCount++;
  }
  if (options?.billingEnabled !== false) {
    recordOwnedUsage(this.usageIdentity(), reported ? usage : null);
    try {
      LLMClientBase.onUsage?.(this.model, usage);
    } catch {
      // An observer failure must never retry an already billed provider request.
      logger.warn("llm.usage_observer_failed");
    }
  }
}

private usageIdentity() {
  return { provider: this.provider, model: this.model, providerKind: this.config.providerKind };
}

/** A streamed usage snapshot updates its receipt without incrementing foreground totals. */
protected recordAttemptUsage(usage: TokenUsage, options?: CreateMessageOptions): void {
  if (options?.billingEnabled !== false) recordOwnedUsage(this.usageIdentity(), usage);
}

/** Host accounting wrapper; provider wire parameters are unchanged. */
withUsageAccounting<T>(options: CreateMessageOptions, operation: () => Promise<T>): Promise<T> {
  const track = () =>
    withUsageAttempt(this.usageIdentity(), options.billingEnabled !== false, operation);
  return options.usagePurpose ? withUsagePurpose(options.usagePurpose, track) : track();
}

getUsage(): LLMUsageTracker {
  return { ...this.usage };
}

begin(
  owner: UsageOwner,
  identity: UsageIdentity,
  external?: { source: string; requestId: string; usage?: TokenUsage },
  physicalRequestId?: string,
): UsageReceipt {
  if (
    owner.ledger !== this ||
    ![identity.provider, identity.model].every(textId) ||
    (identity.providerKind !== undefined && !textId(identity.providerKind)) ||
    (physicalRequestId !== undefined && !/^[a-f0-9]{64}$/.test(physicalRequestId)) ||
    (external !== undefined && physicalRequestId !== undefined)
  )
    throw new Error("Invalid usage identity");
  const requestId =
    physicalRequestId ??
    createHash("sha256")
      .update(
        JSON.stringify([
          this.namespace,
          external?.source ?? "provider",
          external?.requestId ?? randomUUID(),
        ]),
      )
      .digest("hex");
  const receipt: UsageReceipt = {
    version: 1,
    requestId,
    namespace: this.namespace,
    runtimeId: this.runtimeId,
    sessionId: owner.sessionId,
    accountingSessionId: owner.accountingSessionId,
    ...(owner.runId ? { runId: owner.runId } : {}),
    ancestors: [...owner.ancestors],
    ancestorAccountingIds: [...owner.ancestorAccountingIds],
    purpose: external ? "external" : owner.purpose,
    provider: identity.provider,
    model: identity.model,
    ...(identity.providerKind ? { providerKind: identity.providerKind } : {}),
    source: external?.source ?? "provider",
    startedAt: this.now(),
    outcome: "pending",
    usage: null,
    estimatedCostUsd: null,
    pricing: null,
  };
  if (external) {
    receipt.usage = normalizeUsage(external.usage);
    if (receipt.usage) Object.assign(receipt, estimateReceipt(receipt, receipt.usage));
    receipt.outcome = "completed";
    receipt.settledAt = this.now();
  }
  if (external && this.persist(receipt, true) === "exists")
    throw new Error("External usage identity conflict");
  this.records.set(requestId, receipt);
  if (!external) this.persist(receipt);
  return receipt;
}

settle(receipt: UsageReceipt, value: TokenUsage | null): void {
  if (receipt.transmission === "not-sent") return;
  const usage = normalizeUsage(value);
  if (usage) {
    receipt.usage = usage;
    Object.assign(receipt, estimateReceipt(receipt, usage));
  }
  receipt.settledAt = this.now();
  this.persist(receipt);
}

finish(receipt: UsageReceipt, outcome: "completed" | "failed"): void {
  receipt.outcome = outcome;
  receipt.settledAt = this.now();
  this.persist(receipt);
}

markNotSent(receipt: UsageReceipt): void {
  receipt.transmission = "not-sent";
  receipt.outcome = "failed";
  receipt.usage = { promptTokens: 0, completionTokens: 0, totalTokens: 0 };
  receipt.estimatedCostUsd = 0;
  receipt.settledAt = this.now();
  this.persist(receipt);

export abstract class LLMClientBase {
  readonly provider: string;
  readonly model: string;
  readonly maxTokens: number | undefined;
  readonly temperature: number;
  readonly timeout: number;
  readonly retryMaxAttempts: number;
  readonly imageDetail?: ClientDefaults["imageDetail"];
  protected readonly fetch?: ClientDefaults["fetch"];

  /**
   * Process-wide hook fired on every LLM response. The CLI installs this in
   * main.ts to feed the cost tracker; lives on the base class so every code
   * path (REPL, run, arena, sub-agents) reports through one funnel without
   * each call site needing to remember.
   */
  static onUsage?: (model: string, usage: TokenUsage) => void;

  protected usage: LLMUsageTracker = emptyUsageTracker();

  /**
   * `config` carries model identity (provider/model/apiKey/baseUrl/maxTokens/
   * thinking/providerKind). `defaults` carries cross-model runtime knobs
   * (temperature/timeout/retryMaxAttempts/imageDetail/fetch) — those are owned by
   * the Engine and stay stable across hot model switches.
   */
  constructor(
    protected readonly config: LLMConfig,
    defaults?: ClientDefaults,
  ) {
    this.provider = config.provider;
    this.model = config.model;
    // No `?? 8192` fallback: when the model's output ceiling is unknown we keep
    // `undefined` so each provider decides (OpenAI omits the field and lets the
    // endpoint use its own max; Anthropic, where max_tokens is required, supplies
    // a conservative default at request time). Forcing 8192 here truncated long
    // outputs — a streamed tool-arg JSON cut off mid-token → "Missing file_path".
    this.maxTokens = config.maxTokens;
    this.temperature = defaults?.temperature ?? 0.3;
    this.timeout = defaults?.timeout ?? 120_000;
    this.retryMaxAttempts = defaults?.retryMaxAttempts ?? 3;
    this.imageDetail = defaults?.imageDetail;
    this.fetch = usageTrackingFetch(
      requestBoundaryFetch(
        modelTraceFetch(defaults?.fetch ?? globalThis.fetch),
        currentUsageAttempt,
        markCurrentUsageAttemptNotSent,
